/* tally con latido cuando cambia el conteo */
.tal{position:relative}
.tal.fav{--tc:var(--ok)}.tal.con{--tc:var(--fail)}.tal.dep{--tc:var(--work)}
.tal::after{content:'';position:absolute;inset:-2px;border:2px solid var(--tc,var(--grid));opacity:0;pointer-events:none}
